import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.DHmNT4rz.js";const k=JSON.parse('{"title":"Local full stack (Docker Compose)","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"guide/local-stack.md","filePath":"guide/local-stack.md","lastUpdated":null}'),o={name:"guide/local-stack.md"};function r(d,e,n,l,h,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/docs/LOCAL-STACK.md" target="_blank" rel="noreferrer"><code>docs/LOCAL-STACK.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="local-full-stack-docker-compose" tabindex="-1">Local full stack (Docker Compose) <a class="header-anchor" href="#local-full-stack-docker-compose" aria-label="Permalink to &quot;Local full stack (Docker Compose)&quot;">​</a></h1><p>Run every app and infrastructure service locally with one command.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.docker.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.docker</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set BETTER_AUTH_SECRET (vp run auth:secret)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:up:build</span></span></code></pre></div><p>Services:</p><table tabindex="0"><thead><tr><th>Service</th><th>URL</th><th>Purpose</th></tr></thead><tbody><tr><td>Web</td><td><a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a></td><td>TanStack Start UI</td></tr><tr><td>Server</td><td><a href="http://localhost:5000/server" target="_blank" rel="noreferrer">http://localhost:5000/server</a></td><td>Hono API + auth</td></tr><tr><td>PostgreSQL</td><td>localhost:5432</td><td>Primary database</td></tr><tr><td>Redis</td><td>localhost:6379</td><td>Cache + BullMQ</td></tr><tr><td>MinIO</td><td><a href="http://localhost:9000" target="_blank" rel="noreferrer">http://localhost:9000</a> (console :9001)</td><td>S3-compatible uploads</td></tr><tr><td>imgproxy</td><td><a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a></td><td>Avatar/image optimization</td></tr><tr><td>Worker</td><td>(no HTTP port)</td><td>Background jobs</td></tr></tbody></table><h2 id="what-is-enabled-by-default-in-docker" tabindex="-1">What is enabled by default in Docker <a class="header-anchor" href="#what-is-enabled-by-default-in-docker" aria-label="Permalink to &quot;What is enabled by default in Docker&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Default in Compose</th><th>Toggle</th></tr></thead><tbody><tr><td>Auth (email/password)</td><td>On</td><td>Always</td></tr><tr><td>OAuth (GitHub/Google)</td><td>Off</td><td>Set <code>GOOGLE_*</code> / <code>GITHUB_*</code></td></tr><tr><td>SSO / SAML</td><td>On (feature flag)</td><td>Console settings + scale/enterprise plan</td></tr><tr><td>2FA</td><td>On</td><td>User security page</td></tr><tr><td>Redis cache + queues</td><td>On</td><td><code>REDIS_URL</code> (required in production; see escape hatch below)</td></tr><tr><td>BullMQ workers</td><td>On</td><td>Requires Redis + worker service</td></tr><tr><td>Webhook delivery</td><td>On</td><td>Requires Redis; inline without Redis</td></tr><tr><td>MinIO object storage</td><td>On</td><td><code>MINIO_*</code> vars (pre-filled)</td></tr><tr><td>Local disk media fallback</td><td>Off when MinIO set</td><td>Clear <code>MINIO_ENDPOINT</code></td></tr><tr><td>imgproxy</td><td>On</td><td><code>VITE_IMGPROXY_URL</code> on web</td></tr><tr><td>Stripe billing</td><td>Off (sample mode)</td><td><code>STRIPE_SECRET_KEY</code></td></tr><tr><td>Transactional email</td><td>Console log only</td><td><code>MAIL_PROVIDER=resend|smtp</code></td></tr><tr><td>OpenAPI docs</td><td>Off in compose default</td><td><code>ENABLE_OPEN_API_DOCS=true</code> in <code>.env.docker.example</code> for local exploration</td></tr><tr><td>Invitation expiry cron</td><td>On</td><td><code>WORKER_SCHEDULE_INVITATION_CRON</code></td></tr><tr><td>SAML test IdP</td><td>Off</td><td><code>docker compose --profile sso-test up sso-idp</code> — see <a href="/SaaSWeave/guide/sso-testing">SSO-TESTING.md</a></td></tr></tbody></table><h2 id="environment-file" tabindex="-1">Environment file <a class="header-anchor" href="#environment-file" aria-label="Permalink to &quot;Environment file&quot;">​</a></h2><p>Copy <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.env.docker.example" target="_blank" rel="noreferrer"><code>.env.docker.example</code></a> to <code>.env.docker</code>. All variables are documented there.</p><p>For native development (<code>pnpm run dev</code>), copy <a href="https://github.com/mathias7799/SaaSWeave/blob/main/packages/env/.env.example" target="_blank" rel="noreferrer"><code>packages/env/.env.example</code></a> to the ignored <code>packages/env/.env</code> file.</p><p><strong>Production Redis:</strong> when <code>NODE_ENV=production</code>, <code>REDIS_URL</code> is required so cache and rate limits are shared across replicas. For intentional single-instance production deploys only, set <code>ALLOW_SINGLE_INSTANCE_FALLBACK=true</code> (documented in <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.env.docker.example" target="_blank" rel="noreferrer"><code>.env.docker.example</code></a>).</p><h2 id="database-migrations" tabindex="-1">Database migrations <a class="header-anchor" href="#database-migrations" aria-label="Permalink to &quot;Database migrations&quot;">​</a></h2><p>Migrations are <strong>not</strong> run when the server or worker boots. They run as an explicit one-shot step before those services start.</p><p><strong>Docker Compose:</strong> the <code>migrate</code> service builds the server migrator image, waits for Postgres to be healthy, runs <code>vp run db:migrate</code>, and exits. <code>server</code> and <code>worker</code> depend on <code>migrate</code> with <code>condition: service_completed_successfully</code>, so they only start after migrations succeed.</p><p><strong>Local (native dev):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @saasweave/db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or from repo root:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:migrate</span></span></code></pre></div><p><strong>Coolify / production deploy:</strong> run the same migrate command as a <strong>pre-deploy</strong> (release) step before rolling out new server/worker containers — not on every replica boot. Example pre-deploy command inside the migrator/server image:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:migrate</span></span></code></pre></div><p>Ensure <code>DATABASE_URL</code> (and other required env vars) are available to that step. Concurrent pre-deploy runs are safe: the migrator takes a Postgres session advisory lock (<code>pg_advisory_lock</code>) so only one process applies migrations at a time.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:up</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # start (no rebuild)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:up:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # rebuild images and start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker:down</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # stop and remove containers</span></span></code></pre></div><p>Underlying:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dotenvx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><h2 id="health-checks" tabindex="-1">Health checks <a class="header-anchor" href="#health-checks" aria-label="Permalink to &quot;Health checks&quot;">​</a></h2><ul><li>Server: <code>GET /server/health/live</code> (liveness), <code>GET /server/health/ready</code> (readiness)</li><li>Web: <code>GET /_api/health/live</code></li><li>Worker: <code>GET http://localhost:9100/health/ready</code> (Docker maps <code>WORKER_HEALTH_PORT</code>)</li><li>Metrics: <code>GET /server/metrics</code>, worker <code>GET :9100/metrics</code></li><li>Auth providers: <code>GET /server/auth/providers</code></li><li>MinIO: <code>GET /minio/health/live</code></li></ul><p>Production operations (backups, retention, alerts): <a href="https://github.com/mathias7799/SaaSWeave/blob/main/docs/PRODUCTION-OPERATIONS.md" target="_blank" rel="noreferrer">PRODUCTION-OPERATIONS.md</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Migrations fail</strong> — ensure <code>POSTGRES_PASSWORD</code> matches <code>DATABASE_URL</code>.</p><p><strong>Worker idle</strong> — confirm <code>REDIS_URL</code> points at the <code>redis</code> service hostname inside Compose (<code>redis://redis:6379/0</code>).</p><p><strong>Uploads 403</strong> — wait for <code>minio-init</code> to finish; check MinIO console at :9001.</p><p><strong>imgproxy broken images</strong> — set <code>VITE_IMGPROXY_SIGNATURE=insecure</code> for local imgproxy with <code>IMGPROXY_ALLOW_INSECURE=1</code>.</p><p><strong>Stale API routes after code changes</strong> — run <code>pnpm run docker:up:build</code>.</p><h2 id="sso-saml-testing" tabindex="-1">SSO / SAML testing <a class="header-anchor" href="#sso-saml-testing" aria-label="Permalink to &quot;SSO / SAML testing&quot;">​</a></h2><p>The default stack does not include an Identity Provider. To verify console SSO registration and SP-initiated login against a local SimpleSAMLphp IdP:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dotenvx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sso-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sso-idp</span></span></code></pre></div><p>Full runbook (metadata URLs, console field values, demo user, manual login steps): <strong><a href="/SaaSWeave/guide/sso-testing">SSO-TESTING.md</a></strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="https://github.com/mathias7799/SaaSWeave/blob/main/docs/README.md" target="_blank" rel="noreferrer">docs/README.md</a> — per-package documentation</li><li><a href="/SaaSWeave/guide/sso-testing">docs/SSO-TESTING.md</a> — local SAML IdP runbook</li></ul>`,40)])])}const g=t(o,[["render",r]]);export{k as __pageData,g as default};
